from pathlib import Path
import sys
root=Path(sys.argv[1] if len(sys.argv)>1 else '.')
engine_path=root/'live_server'/'v4_engine.py'
api_path=root/'live_server'/'api.py'
app_path=root/'app.py'
engine=engine_path.read_text(encoding='utf-8')
api=api_path.read_text(encoding='utf-8')
app=app_path.read_text(encoding='utf-8')
engine_anchor="    def validation_marks(self,market=None,limit=1000):\n        sql='SELECT id,ts,market,symbol,state,anchor_price,power,power_delta,finder_rank,setup_count,trigger_count,rvol,volume_ratio,hard_floor,warning_floor,floor_mode,ret_5m,ret_15m,ret_30m,ret_60m,mfe_pct,mae_pct,settled_at FROM v4_validation_marks'; args=[]\n"
episode_method="    def validation_episodes(self,market=None,limit=5000,bridge_minutes=5):\n        # Derive signal episodes from minute validation snapshots.\n        rows=self.validation_marks(market,limit)\n        if not rows:return []\n\n        active={'SETUP','READY','ENTRY','HOLD','PARTIAL_EXIT','EXIT_READY','HARD_EXIT'}\n        level={'SETUP':1,'READY':2,'ENTRY':3,'HOLD':4,'PARTIAL_EXIT':5,'EXIT_READY':6,'HARD_EXIT':7}\n        rows=sorted(rows,key=lambda r:(str(r.get('symbol') or ''),str(r.get('ts') or '')))\n        current={}; episodes=[]\n\n        def dt(v):\n            try:\n                x=datetime.fromisoformat(str(v).replace('Z','+00:00'))\n                return x if x.tzinfo else x.replace(tzinfo=timezone.utc)\n            except Exception:return None\n\n        def finish(sym,cur):\n            if not cur:return\n            start=cur['start']\n            first_ts=dt(start.get('ts')); last_ts=dt(cur.get('last_active_ts'))\n            duration=((last_ts-first_ts).total_seconds()/60) if first_ts and last_ts else 0.0\n            path=cur.get('path') or []\n            max_state=max(path,key=lambda s:level.get(s,0)) if path else str(start.get('state') or 'SETUP')\n            episodes.append({\n                'market':start.get('market'),'symbol':sym,\n                'start_ts':start.get('ts'),'end_ts':cur.get('last_active_ts'),\n                'duration_min':round(max(0.0,duration),1),\n                'start_state':start.get('state'),'max_state':max_state,\n                'state_path':' → '.join(path),\n                'anchor_price':start.get('anchor_price'),\n                'start_power':start.get('power'),'max_power':cur.get('max_power'),\n                'start_power_delta':start.get('power_delta'),\n                'finder_rank':start.get('finder_rank'),\n                'start_setup':start.get('setup_count'),'max_setup':cur.get('max_setup'),\n                'start_trigger':start.get('trigger_count'),'max_trigger':cur.get('max_trigger'),\n                'rvol':start.get('rvol'),'volume_ratio':start.get('volume_ratio'),\n                'ret_5m':start.get('ret_5m'),'ret_15m':start.get('ret_15m'),\n                'ret_30m':start.get('ret_30m'),'ret_60m':start.get('ret_60m'),\n                'mfe_pct':start.get('mfe_pct'),'mae_pct':start.get('mae_pct'),\n                'settled_at':start.get('settled_at'),\n                'settled':start.get('ret_60m') is not None,\n            })\n\n        for r in rows:\n            sym=str(r.get('symbol') or '').upper()\n            if not sym:continue\n            state=str(r.get('state') or 'WATCH').upper()\n            ts=dt(r.get('ts')); cur=current.get(sym)\n\n            if state in active:\n                if cur:\n                    last=dt(cur.get('last_active_ts'))\n                    gap=((ts-last).total_seconds()/60) if ts and last else 999\n                    if gap>bridge_minutes:\n                        finish(sym,cur); cur=None\n                if not cur:\n                    cur={'start':r,'last_active_ts':r.get('ts'),'path':[state],\n                         'max_power':_f(r.get('power')),\n                         'max_setup':int(_f(r.get('setup_count'))),\n                         'max_trigger':int(_f(r.get('trigger_count')))}\n                else:\n                    cur['last_active_ts']=r.get('ts')\n                    if not cur['path'] or cur['path'][-1]!=state:cur['path'].append(state)\n                    cur['max_power']=max(_f(cur.get('max_power')),_f(r.get('power')))\n                    cur['max_setup']=max(int(_f(cur.get('max_setup'))),int(_f(r.get('setup_count'))))\n                    cur['max_trigger']=max(int(_f(cur.get('max_trigger'))),int(_f(r.get('trigger_count'))))\n                current[sym]=cur\n            elif cur:\n                last=dt(cur.get('last_active_ts'))\n                gap=((ts-last).total_seconds()/60) if ts and last else 999\n                if gap>bridge_minutes:\n                    finish(sym,cur); current.pop(sym,None)\n\n        for sym,cur in list(current.items()):finish(sym,cur)\n        episodes.sort(key=lambda x:str(x.get('start_ts') or ''),reverse=True)\n        for i,e in enumerate(episodes,1):e['episode_id']=i\n        return episodes\n\n"
api_anchor="@app.get('/api/v4/validation/marks')\ndef v4_validation_marks(market:str|None=None,limit:int=Query(1000,ge=1,le=5000)):\n    return {'data':v4.store.validation_marks(market,limit),'note':'Forward-return marks: +5/+15/+30/+60m and MFE/MAE. Heuristic diagnostics, not probabilities.'}\n"
api_extra="\n@app.get('/api/v4/validation/episodes')\ndef v4_validation_episodes(market:str|None=None,limit:int=Query(5000,ge=1,le=10000),bridge_minutes:int=Query(5,ge=1,le=15)):\n    return {\n        'data':v4.store.validation_episodes(market,limit,bridge_minutes),\n        'note':'Signal episodes derived from minute validation snapshots. Brief inactive flickers are bridged; episode count is closer to independent signal cycles than raw snapshot count.'\n    }\n"
ui_anchor="        st.markdown('#### 🧭 오늘 엔진 판정')\n"
episode_ui="        st.markdown('#### 🧩 Episode Validation')\n        st.caption('분당 스냅샷을 그대로 세지 않고 SETUP→READY→ENTRY→EXIT 계열의 연속 신호를 하나의 Episode로 묶어 봅니다. 짧은 WATCH 흔들림은 5분까지 같은 Episode로 합칩니다.')\n        eps=api(f'/api/v4/validation/episodes?market={m}&limit=5000&bridge_minutes=5').get('data') or []\n        if eps:\n            edf=pd.DataFrame(eps)\n            edf['start_dt']=pd.to_datetime(edf['start_ts'],utc=True,errors='coerce')\n            if m=='USA':\n                try:edf['episode_date']=edf['start_dt'].dt.tz_convert('America/New_York').dt.date.astype(str)\n                except Exception:edf['episode_date']=edf['start_dt'].dt.date.astype(str)\n            else:\n                try:edf['episode_date']=edf['start_dt'].dt.tz_convert('Asia/Seoul').dt.date.astype(str)\n                except Exception:edf['episode_date']=edf['start_dt'].dt.date.astype(str)\n            e=edf[edf['episode_date']==report_date].copy() if report_date else edf.copy()\n            for col in ['start_power','max_power','start_setup','max_setup','start_trigger','max_trigger','ret_5m','ret_15m','ret_30m','ret_60m','mfe_pct','mae_pct','duration_min']:\n                if col in e.columns:e[col]=pd.to_numeric(e[col],errors='coerce')\n\n            ec1,ec2,ec3,ec4=st.columns(4)\n            ec1.metric('Episode 수',len(e))\n            ec2.metric('60분 완료',int(e['ret_60m'].notna().sum()) if 'ret_60m' in e.columns else 0)\n            ec3.metric('READY 이상',int(e['max_state'].isin(['READY','ENTRY','HOLD','PARTIAL_EXIT','EXIT_READY','HARD_EXIT']).sum()) if 'max_state' in e.columns else 0)\n            ec4.metric('ENTRY 도달',int(e['max_state'].isin(['ENTRY','HOLD','PARTIAL_EXIT','EXIT_READY','HARD_EXIT']).sum()) if 'max_state' in e.columns else 0)\n\n            if len(e):\n                state_perf=[]\n                for state,g in e.groupby('max_state',dropna=False):\n                    r={'최고상태':stko(state),'Episode':len(g)}\n                    for col,label in [('ret_5m','5분%'),('ret_15m','15분%'),('ret_30m','30분%'),('ret_60m','60분%')]:\n                        vals=g[col].dropna() if col in g.columns else pd.Series(dtype=float)\n                        r[label]=round(vals.mean(),3) if len(vals) else None\n                    r['60분상승%']=round((g['ret_60m'].dropna()>0).mean()*100,1) if 'ret_60m' in g.columns and g['ret_60m'].notna().any() else None\n                    r['MFE%']=round(g['mfe_pct'].mean(),3) if 'mfe_pct' in g.columns and g['mfe_pct'].notna().any() else None\n                    r['MAE%']=round(g['mae_pct'].mean(),3) if 'mae_pct' in g.columns and g['mae_pct'].notna().any() else None\n                    state_perf.append(r)\n                st.markdown('##### Episode 최고 상태별 성과')\n                st.dataframe(pd.DataFrame(state_perf),use_container_width=True,hide_index=True)\n\n                ep=e[e['start_power'].notna()].copy() if 'start_power' in e.columns else pd.DataFrame()\n                if len(ep):\n                    ep['Power구간']=pd.cut(ep['start_power'],bins=[-1e9,0,20,40,60,1e9],labels=['≤0','0~20','20~40','40~60','60+'],right=False)\n                    buckets=[]\n                    for bucket,g in ep.groupby('Power구간',observed=True):\n                        r={'시작 Power':str(bucket),'Episode':len(g)}\n                        for col,label in [('ret_15m','15분%'),('ret_30m','30분%'),('ret_60m','60분%')]:\n                            vals=g[col].dropna() if col in g.columns else pd.Series(dtype=float)\n                            r[label]=round(vals.mean(),3) if len(vals) else None\n                        r['60분상승%']=round((g['ret_60m'].dropna()>0).mean()*100,1) if 'ret_60m' in g.columns and g['ret_60m'].notna().any() else None\n                        buckets.append(r)\n                    st.markdown('##### Episode 시작 Power별 성과')\n                    st.dataframe(pd.DataFrame(buckets),use_container_width=True,hide_index=True)\n\n                st.markdown('##### Episode 목록')\n                cols=[c for c in ['start_ts','symbol','start_state','max_state','state_path','duration_min','anchor_price','start_power','max_power','start_setup','max_setup','start_trigger','max_trigger','ret_5m','ret_15m','ret_30m','ret_60m','mfe_pct','mae_pct'] if c in e.columns]\n                st.dataframe(e[cols].sort_values('start_ts',ascending=False),use_container_width=True,hide_index=True)\n        else:\n            st.caption('Episode를 만들 수 있는 Validation 데이터가 아직 없습니다.')\n\n"
footer_old="st.caption('V4.4.9 UI · FINDER + LIGHT20 + FRESH + VALIDATION DAILY REPORT · MAX 5 HEAVY TRACKING · MANUAL ORDER ONLY')"
footer_new="st.caption('V4.5.0 · EPISODE VALIDATION + DAILY REPORT · MAX 5 HEAVY TRACKING · MANUAL ORDER ONLY')"
if engine_anchor not in engine: raise SystemExit('PATCH ABORTED: validation_marks anchor not found; no files changed.')
if api_anchor not in api: raise SystemExit('PATCH ABORTED: validation marks API anchor not found; no files changed.')
if ui_anchor not in app: raise SystemExit('PATCH ABORTED: V4.4.9 Validation UI anchor not found; no files changed.')
engine2=engine.replace(engine_anchor,episode_method+engine_anchor,1)
api2=api.replace(api_anchor,api_anchor+api_extra,1)
app2=app.replace(ui_anchor,episode_ui+ui_anchor,1)
if footer_old in app2: app2=app2.replace(footer_old,footer_new,1)
engine_path.write_text(engine2,encoding='utf-8')
api_path.write_text(api2,encoding='utf-8')
app_path.write_text(app2,encoding='utf-8')
print('PATCHED:',engine_path)
print('PATCHED:',api_path)
print('PATCHED:',app_path)
